select throws_ok($$select public.native_admin_execute('00000000-0000-4000-8000-000000001628','https://clerk.admin.test','finish_payment_sync','{"account_ids":[]}','sandbox')$$,'42501','native_admin_forbidden','solo owner puede dar por completo el historial leído');
select * from finish(); rollback;
